package com.furryfemboy.entity;
import com.furryfemboy.FurryFemboyMod; import com.furryfemboy.config.ModConfig; import com.furryfemboy.item.GodzillaWeaponItem; import com.furryfemboy.registry.ModEntities; import com.furryfemboy.registry.ModItems; import com.furryfemboy.registry.ModSounds; import software.bernie.geckolib.animatable.GeoEntity; import software.bernie.geckolib.core.animatable.instance.AnimatableInstanceCache; import software.bernie.geckolib.core.animation.*; import software.bernie.geckolib.core.object.PlayState; import software.bernie.geckolib.util.GeckoLibUtil; import net.minecraft.nbt.CompoundTag; import net.minecraft.network.syncher.*; import net.minecraft.server.level.ServerLevel; import net.minecraft.server.level.ServerPlayer; import net.minecraft.sounds.SoundEvent; import net.minecraft.world.*; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.goal.*; import net.minecraft.world.entity.ai.goal.target.*; import net.minecraft.world.entity.animal.TamableAnimal; import net.minecraft.world.entity.monster.Monster; import net.minecraft.world.entity.player.Player; import net.minecraft.world.item.*; import net.minecraft.world.level.Level; import net.minecraft.world.phys.AABB; import java.util.*;
public class FurryFemboyEntity extends TamableAnimal implements GeoEntity {
 private static final EntityDataAccessor<Integer> MODE=SynchedEntityData.defineId(FurryFemboyEntity.class,EntityDataSerializers.INT); private static final int FOLLOW=0,SIT=1,GUARD=2,PASSIVE=3; private final AnimatableInstanceCache cache=GeckoLibUtil.createInstanceCache(this); private int attackCooldown;
 public FurryFemboyEntity(EntityType<? extends TamableAnimal> type,Level level){super(type,level);setMaxUpStep(.9f);}
 public static net.minecraft.world.entity.ai.attributes.AttributeSupplier.Builder createAttributes(){ return Mob.createMobAttributes().add(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH, ModConfig.HEALTH.get()).add(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED, ModConfig.SPEED.get()).add(net.minecraft.world.entity.ai.attributes.Attributes.ATTACK_DAMAGE, 4.0); }
 public static boolean checkFurrySpawn(EntityType<FurryFemboyEntity> type, net.minecraft.world.level.ServerLevelAccessor level, MobSpawnType reason, net.minecraft.core.BlockPos pos, net.minecraft.util.RandomSource random){ return level.getRawBrightness(pos,0)>8 && level.getBlockState(pos.below()).isValidSpawn(level,pos.below(),type); }
 @Override protected void defineSynchedData(){super.defineSynchedData();entityData.define(MODE,FOLLOW);}
 @Override protected void registerGoals(){goalSelector.addGoal(1,new FloatGoal(this)); goalSelector.addGoal(2,new SitWhenOrderedToGoal(this)); goalSelector.addGoal(3,new MeleeAttackGoal(this,1.2,true)); goalSelector.addGoal(4,new FollowOwnerGoal(this,1.15,5,35,false)); goalSelector.addGoal(5,new WaterAvoidingRandomStrollGoal(this,1)); goalSelector.addGoal(6,new LookAtPlayerGoal(this,Player.class,8)); goalSelector.addGoal(7,new RandomLookAroundGoal(this)); targetSelector.addGoal(1,new OwnerHurtByTargetGoal(this)); targetSelector.addGoal(2,new OwnerHurtTargetGoal(this)); targetSelector.addGoal(3,new HurtByTargetGoal(this)); targetSelector.addGoal(4,new NearestAttackableTargetGoal<>(this,Monster.class,true,e->getMode()!=PASSIVE)); }
 @Override public boolean isFood(ItemStack s){return s.is(Items.MILK_BUCKET);}
 @Override public InteractionResult mobInteract(Player p,InteractionHand hand){ItemStack s=p.getItemInHand(hand); if(isTame()){if(isOwnedBy(p)){if(p.isShiftKeyDown()){cycleMode(); p.displayClientMessage(net.minecraft.network.chat.Component.translatable("entity.furryfemboy.mode."+getModeName()),true); return InteractionResult.SUCCESS;} if(s.is(Items.MILK_BUCKET)&&getHealth()<getMaxHealth()){heal(8); if(!p.getAbilities().instabuild)p.setItemInHand(hand,new ItemStack(Items.BUCKET)); return InteractionResult.SUCCESS;} setOrderedToSit(!isOrderedToSit()); return InteractionResult.SUCCESS;} return InteractionResult.PASS;} if(s.is(Items.MILK_BUCKET)&&!level().isClientSide){ if(random.nextFloat()<ModConfig.TAME_CHANCE.get()){tame(p); setTarget(null); level().broadcastEntityEvent(this,(byte)7); if(!p.getAbilities().instabuild)p.setItemInHand(hand,new ItemStack(Items.BUCKET));} else level().broadcastEntityEvent(this,(byte)6); return InteractionResult.SUCCESS;} return super.mobInteract(p,hand);}
 private void cycleMode(){entityData.set(MODE,(getMode()+1)%4); if(getMode()==SIT)setOrderedToSit(true); else setOrderedToSit(false);}
 public int getMode(){return entityData.get(MODE);} public String getModeName(){return switch(getMode()){case SIT->"sit";case GUARD->"guard";case PASSIVE->"passive";default->"follow";};}
 @Override public void addAdditionalSaveData(CompoundTag t){super.addAdditionalSaveData(t);t.putInt("BehaviorMode",getMode());}
 @Override public void readAdditionalSaveData(CompoundTag t){super.readAdditionalSaveData(t);entityData.set(MODE,t.getInt("BehaviorMode"));}
 @Override public boolean hurt(DamageSource src,float amount){return super.hurt(src,amount);}
 @Override public void tick(){super.tick(); if(attackCooldown>0)attackCooldown--; if(!level().isClientSide&&isTame()&&getMode()!=PASSIVE&&getTarget()!=null&&attackCooldown==0){GodzillaWeaponItem.fire(this);attackCooldown=28;} if(isTame()&&getOwner()!=null&&distanceToSqr(getOwner())>1600)teleportTo(getOwner().getX(),getOwner().getY(),getOwner().getZ());}
 @Override public void registerControllers(AnimatableManager.ControllerRegistrar c){c.add(new AnimationController<>(this,"main",5,state->{if(state.isMoving())return state.setAndContinue(RawAnimation.begin().thenLoop("animation.furry.walk"));return state.setAndContinue(RawAnimation.begin().thenLoop("animation.furry.idle"));}));}
 @Override public AnimatableInstanceCache getAnimatableInstanceCache(){return cache;}
 @Override protected SoundEvent getHurtSound(DamageSource d){return ModSounds.FURRY_HURT.get();} @Override protected SoundEvent getAmbientSound(){return ModSounds.FURRY_HAPPY.get();} @Override public float getVoicePitch(){return 1.2f;}
 @Override public void handleEntityEvent(byte id){if(id==7)for(int i=0;i<7;i++)level().addParticle(net.minecraft.core.particles.ParticleTypes.HEART,getRandomX(1),getRandomY(),getRandomZ(1),0,0,0);super.handleEntityEvent(id);}
}
